    void offersNeedConsent() throws Exception {
        FakeContext c = new FakeContext();
        Main m = start(c);
        m.handle("create", Map.of("customerId", "c1", "consent", "explicit"));
        m.handle("create", Map.of("customerId", "c2", "consent", "none"));
